using PedagoraPilot.Domain.Common;
using PedagoraPilot.Domain.Identifiers;

namespace PedagoraPilot.Domain.Access;

// These are entities of the OrganizationMember aggregate, not independent aggregates.
// A member can hold several roles at once; each role has its own table for product-side
// tracking while identity remains centralized in OrganizationMember/AuthGate.
public sealed class OrganizationAdministratorProfile : Entity { private OrganizationAdministratorProfile() { } public OrganizationAdministratorProfile(Guid id, OrganizationMemberId memberId, Guid organizationId) : base(id) { MemberId=memberId; OrganizationId=organizationId; IsActive=true; } public OrganizationMemberId MemberId {get;private set;} public Guid OrganizationId {get;private set;} public bool IsActive {get;private set;} public void SetActive(bool value)=>IsActive=value; }
